'use strict';
const $=id=>document.getElementById(id),t=OrionI18n.t;
const phases=[['New Moon','新月'],['Waxing crescent','眉月（漸盈）'],['First quarter','上弦月'],['Waxing gibbous','盈凸月'],['Full Moon','滿月'],['Waning gibbous','虧凸月'],['Last quarter','下弦月'],['Waning crescent','殘月（漸虧）']];
const journeys=[[1,7,4],[2,6,0],[3,5,4],[7,1,0],[6,2,4],[5,3,0],[1,5,2],[7,3,6]];
let variant=OrionProgress.variant('moonphases'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget;
let stage=0,position=0,solved=false,hintDepth=0,state='ready',saveFailed=false,drag=null;
function target(v=variant,s=stage){return journeys[v][s];}
function illumination(p){return (1-Math.cos(p*Math.PI/4))/2;}
function trend(p){return p===0?t('Beginning of the lit-face cycle','受光面變化週期的起點'):p===4?t('Fully lit face; next it shrinks','整個面向地球的面受光；之後漸減'):p<4?t('Waxing: the lit part grows as time moves forward','漸盈：時間前進，亮的部分增加'):t('Waning: the lit part shrinks as time moves forward','漸虧：時間前進，亮的部分減少');}
function resetTrial(){position=(target()+3)%8;solved=false;hintDepth=0;state='ready';saveFailed=false;drag=null;$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('moonphases')){variant=v;stage=0;resetTrial();}
function setPosition(p){if(solved||!Number.isInteger(p)||p<0||p>7)return;position=p;state='ready';render();}
function step(d){if(d!==1&&d!==-1)return;setPosition((position+d+8)%8);}
// Project the illuminated hemisphere onto a north-up Earth-facing disk.
function litPath(p,r=36){if(p===0)return '';const side=p<=4?1:-1,c=Math.cos(p*Math.PI/4),points=[];for(let i=0;i<=48;i++){const y=-r+2*r*i/48,q=Math.sqrt(Math.max(0,r*r-y*y));points.push([side*q,y]);}for(let i=48;i>=0;i--){const y=-r+2*r*i/48,q=Math.sqrt(Math.max(0,r*r-y*y));points.push([side*c*q,y]);}return points.map(([x,y],i)=>`${i?'L':'M'}${(x+42).toFixed(3)} ${(y+42).toFixed(3)}`).join(' ')+'Z';}
function moon(p){return `<svg viewBox="0 0 84 84" aria-hidden="true"><circle cx="42" cy="42" r="36" fill="#233240" stroke="#9baebb"/><path d="${litPath(p)}" fill="#eee8cf"/></svg><p>${t(...phases[p])}</p>`;}
function point(p){const a=p*Math.PI/4;return {x:170+85*Math.cos(a),y:110-85*Math.sin(a)};}
function positionAt(x,y,rect){const scale=Math.min(rect.width/420,rect.height/230),ox=rect.left+(rect.width-420*scale)/2,oy=rect.top+(rect.height-230*scale)/2,dx=(x-ox)/scale-170,dy=110-(y-oy)/scale;if(Math.hypot(dx,dy)<30)return null;return (Math.round(Math.atan2(dy,dx)/(Math.PI/4))+8)%8;}
function dragStart(e){if(solved||drag||e.button!==undefined&&e.button!==0)return;const p=positionAt(e.clientX,e.clientY,$('orbit').querySelector('svg').getBoundingClientRect());if(p===null)return;drag={id:e.pointerId,original:position};$('orbit').setPointerCapture?.(e.pointerId);setPosition(p);}
function dragMove(e){if(!drag||drag.id!==e.pointerId)return;const p=positionAt(e.clientX,e.clientY,$('orbit').querySelector('svg').getBoundingClientRect());if(p!==null)setPosition(p);}
function dragEnd(e,cancel=false){if(!drag||drag.id!==e.pointerId)return;const original=drag.original;if(!cancel)dragMove(e);drag=null;if(cancel)setPosition(original);}
function check(){if(solved||drag)return;if(position===target()){solved=true;state='success';if(stage===2)saveFailed=!OrionProgress.earn('orbit');}else state=Math.abs(illumination(position)-illumination(target()))<1e-8?'mirror':'wrong';render();if(solved&&stage<2)$('next').focus();}
function hints(){const directions=[['right','右方'],['upper right','右上方'],['top','上方'],['upper left','左上方'],['left','左方'],['lower left','左下方'],['bottom','下方'],['lower right','右下方']];return [t('Watch the view from Earth, not the small Moon in the overhead model. The Sun stays on the right.','觀察地球視角，不是俯視模型中的小月亮。太陽固定在右方。'),t('Move forward anticlockwise. From new to full the bright part grows; after full it shrinks. Equal bright amounts can face opposite ways.','向逆時針前進。新月到滿月，亮面增加；滿月之後減少。同樣亮面大小也可能朝相反方向。'),t(`Try the ${directions[target()][0]} orbit stop, then compare and record.`,`試試軌道${directions[target()][1]}的停點，再比較並記錄。`)];}
function render(){const complete=solved&&stage===2,progress=stage+Number(solved),m=point(position);window.OrionDiscovery?.update(complete);document.title=t('The Moonkeeper’s Observatory · Orion','月相守望台 · Orion');$('stageTitle').textContent=t(`Sky view ${stage+1} · Set ${variant+1}`,`第 ${stage+1} 幅天空 · 第 ${variant+1} 組`);$('sceneStatus').textContent=t(`Lunar seals · ${progress} / 3`,`月亮封印 · ${progress} / 3`);$('seals').textContent=Array.from({length:3},(_,i)=>i<progress?'◆':'◇').join(' ');$('scene').classList.toggle('complete',complete);
$('orbit').innerHTML=`<svg viewBox="0 0 420 230" aria-hidden="true"><defs><marker id="arrow" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0 0L6 3L0 6Z" fill="#f0d897"/></marker></defs><circle cx="170" cy="110" r="85" fill="none" stroke="#809da8" stroke-dasharray="4 6"/>${Array.from({length:8},(_,i)=>{const q=point(i);return `<circle cx="${q.x}" cy="${q.y}" r="5" fill="#7c97a1"/>`;}).join('')}<circle cx="170" cy="110" r="23" fill="#296081"/><path d="M170 87 A23 23 0 0 1 170 133Z" fill="#67b1ba"/><text x="170" y="154" text-anchor="middle" fill="#dae5df" font-size="14">${t('Earth','地球')}</text><circle cx="370" cy="110" r="24" fill="#eed083"/><text x="370" y="155" text-anchor="middle" fill="#f0d897" font-size="14">${t('Sun','太陽')}</text>${[65,110,155].map(y=>`<path d="M332 ${y}H287" stroke="#f0d897" stroke-width="2" marker-end="url(#arrow)"/>`).join('')}<path d="M234 57Q214 30 190 23" fill="none" stroke="#f0d897" stroke-width="2" marker-end="url(#arrow)"/><circle cx="${m.x}" cy="${m.y}" r="16" fill="#263744" stroke="#e1e7df" stroke-width="2"/><path d="M${m.x} ${m.y-16}A16 16 0 0 1 ${m.x} ${m.y+16}Z" fill="#eee8cf"/><text x="170" y="223" text-anchor="middle" fill="#dae5df" font-size="12">${t('Overhead model · sunlight ←','俯視模型 · 陽光 ←')}</text></svg>`;
$('orbit').setAttribute('aria-label',t(`Overhead orbit model. Sun on right. Moon at stop ${position+1} of 8. Use the slider or previous/next controls to move it.`,`俯視軌道模型。太陽在右方。月亮在第 ${position+1} 個停點，共 8 個。用滑桿或上一步、下一步控制移動。`));$('position').value=position;$('position').disabled=solved;$('position').setAttribute('aria-valuetext',t(`Stop ${position+1}: ${phases[position][0]}`,`停點 ${position+1}：${phases[position][1]}`));$('previous').disabled=solved;$('forward').disabled=solved;
$('goal').textContent=t(`Match: ${phases[target()][0]}. Check the bright shape AND its side.`,`配對：${phases[target()][1]}。檢查亮面形狀和方向。`);$('targetMoon').innerHTML=moon(target());$('targetMoon').setAttribute('aria-label',t(...phases[target()]));$('currentMoon').innerHTML=moon(position);$('currentMoon').setAttribute('aria-label',t(...phases[position]));$('reading').textContent=trend(position);$('evidence').textContent=t('Earth view: north up · bright side can look rotated in the real sky.','地球視角：北方朝上 · 真實天空中的亮面方向可能旋轉。');
$('feedback').textContent=state==='success'?t('The sky view matches. A lunar seal shines!','天空景象相同，月亮封印亮起了！'):state==='mirror'?t('The bright amount matches, but the side differs. Try the other half of the orbit.','亮面大小相同，但方向不同。試試軌道另一半。'):state==='wrong'?t('Not this view yet. Move the Moon and compare again.','還不是這幅景象。移動月亮，再比較。'):t('Explore the orbit, then record your match.','探索軌道，再記錄你的配對。');
$('check').hidden=solved;$('retry').hidden=solved;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=solved||hintDepth===3;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintDepth>0));$('hints').hidden=!hintDepth;$('hints').innerHTML=hints().slice(0,hintDepth).map(h=>`<li>${h}</li>`).join('');$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Try saving again.','已獲得符印，但儲存失敗。請再次儲存。'):OrionProgress.has('orbit')?t('Orbit Sigil saved in your collection.','環月符印已存入收藏。'):'';}
$('position').oninput=()=>setPosition(Number($('position').value));$('previous').onclick=()=>step(-1);$('forward').onclick=()=>step(1);$('orbit').onpointerdown=dragStart;$('orbit').onpointermove=dragMove;$('orbit').onpointerup=e=>dragEnd(e);$('orbit').onpointercancel=e=>dragEnd(e,true);$('orbit').onlostpointercapture=e=>dragEnd(e,true);
$('check').onclick=check;$('retry').onclick=()=>{if(!solved)resetTrial();};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetTrial();$('position').focus();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);render();};$('replay').onclick=()=>{const v=OrionProgress.nextVariant('moonphases',variant);observedVariant=OrionProgress.variant('moonphases');resetMission(v);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('orbit');render();};
function syncProgress(){const v=OrionProgress.variant('moonphases'),h=OrionProgress.read().hashTarget,changed=v!==observedVariant||h!==observedTarget;observedVariant=v;observedTarget=h;if(changed||solved&&stage===2&&!OrionProgress.has('orbit')&&!saveFailed)resetMission();else render();}
window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);window.addEventListener('pagehide',()=>{if(drag){position=drag.original;drag=null;}});resetMission();OrionI18n.apply();
